const data = items[0].json;

// 1. Pick a random topic, style, and template
const topic = data.topics[Math.floor(Math.random() * data.topics.length)];
const style = data.styles[Math.floor(Math.random() * data.styles.length)];
const template = data.templates[Math.floor(Math.random() * data.templates.length)];

// 2. Pick a random voice object (which contains name and gender)
const randomVoiceObj = data.voiceData[Math.floor(Math.random() * data.voiceData.length)];
const voice = randomVoiceObj.name;
const gender = randomVoiceObj.gender;

// 3. Pre-fill the style into the template description
const description = template
  .replace(/{style}/g, style)
  .replace(/{gender}/g, gender);

return [{
  json: { 
    topic, 
    style, 
    voice, 
    gender, 
    description
  }
}];

const responseData = $input.first().json;
const randomizerData = $node["RANDOMIZER"].json;

// 1. Extract the base64 audio string
let base64Audio = "";
if (responseData.candidates && responseData.candidates[0].content.parts[0].inlineData) {
    base64Audio = responseData.candidates[0].content.parts[0].inlineData.data;
} else if (responseData.data) {
    base64Audio = responseData.data;
}

if (!base64Audio) throw new Error("No audio data found.");

// 2. Create WAV Header (24kHz, 16-bit, Mono)
const pcmBuffer = Buffer.from(base64Audio, 'base64');
const createWavHeader = (pcmLength) => {
    const header = Buffer.alloc(44);
    header.write('RIFF', 0);
    header.writeUInt32LE(36 + pcmLength, 4);
    header.write('WAVE', 8);
    header.write('fmt ', 12);
    header.writeUInt32LE(16, 16);
    header.writeUInt16LE(1, 20);
    header.writeUInt16LE(1, 22); // Channels
    header.writeUInt32LE(24000, 24); // Sample Rate
    header.writeUInt32LE(48000, 28); // Byte Rate
    header.writeUInt16LE(2, 32); // Block Align
    header.writeUInt16LE(16, 34); // Bits per Sample
    header.write('data', 36);
    header.writeUInt32LE(pcmLength, 40);
    return header;
};

const finalWavBuffer = Buffer.concat([createWavHeader(pcmBuffer.length), pcmBuffer]);

// 3. Format Filename: teacher_XXX_YYYYMMDD_HHMMSS.wav
const now = new Date();
const timestamp = now.toISOString().replace(/[-T:]/g, '').split('.')[0];
const randomId = Math.floor(Math.random() * 1000).toString().padStart(3, '0');
const fileName = `teacher_${randomId}_${timestamp}.wav`;
const relativePath = `voices/${fileName}`;

// 4. Construct the EXACT JSON structure from your template
const metadataLine = {
    audio_file: relativePath,
    text: randomizerData.text || "No text found", // Ensure text is passed from previous node
    description: randomizerData.description,
    voice_name: randomizerData.voice,
    style: randomizerData.style,
    topic: randomizerData.topic,
    gender: randomizerData.gender
};

return [{
    json: metadataLine,
    binary: {
        data: {
            data: finalWavBuffer.toString('base64'),
            mimeType: 'audio/wav',
            fileName: fileName,
        }
    }
}];
